parameters.jsCode:
// =============================================================================
// Node 2: ตาราง Mapping คอลัมน์ใน Excel (SHEET_COLUMN_MAP) ตามชีตจริง
// =============================================================================
const SHEET_COLUMN_MAP = {
  "SEA Import": { job: "D", status: "C", etd: "A", eta: "B", customer: "E", bl: "G", draft: "H", advance: "L", do: "N", customs: "O", cleared: "P", remark: "Y" },
  "AIR Import": { job: "D", status: "C", etd: "A", eta: "B", customer: "E", bl: "G", draft: "H", advance: "J", do: "L", customs: "M", cleared: "N", remark: "W" },
  "Air Export": { job: "F", status: "E", etd: "C", eta: "D", customer: "G", bl: "I", draft: "J", advance: "N", do: "P", customs: "Q", cleared: "R", remark: "AA" },
  "SEA Export": { job: "G", status: "F", etd: "D", eta: "E", customer: "H", bl: "J", draft: "K", advance: "O", do: "T", customs: "Q", cleared: "S", remark: "AE" }
};

const body = $json.body || $json || {};
const jobNo = String(body.jobNo || 'SHSI26100024').trim().toUpperCase();
const sourceSheet = String(body.sourceSheet || 'SEA Import');
const sourceRow = Number(body.sourceRow || 412);
const expectedVersion = Number(body.expectedVersion || 1);
const editId = String(body.editId || '00000000-0000-4000-8000-000000000001');
const changes = body.changes || {
  status: 'In Progress',
  statusDetail: 'Control',
  etd: '2026-01-10',
  eta: '2026-10-31',
  draftDate: null,
  customsDate: null,
  doDate: null,
  clearDate: null,
  advanceDate: null,
  remark: 'Updated via Perkin Logistics Web'
};

// แปลงชื่อฟิลด์จากเว็บให้ตรงกับคีย์ใน SHEET_COLUMN_MAP
const fieldAlias = {
  status: 'status',
  etd: 'etd',
  eta: 'eta',
  customer: 'customer',
  bl: 'bl',
  draft: 'draft',
  draftDate: 'draft',
  advance: 'advance',
  advanceDate: 'advance',
  do: 'do',
  doDate: 'do',
  customs: 'customs',
  customsDate: 'customs',
  cleared: 'cleared',
  clearDate: 'cleared',
  remark: 'remark'
};

const statusToExcelText = {
  Completed: 'Job Complete',
  Control: 'Job Control',
  Waiting: 'Job Waiting',
  Cancelled: 'Job Cancelled'
};

const cols = SHEET_COLUMN_MAP[sourceSheet] || SHEET_COLUMN_MAP['SEA Import'];
const patches = [];

for (const [rawKey, rawVal] of Object.entries(changes)) {
  const mapKey = fieldAlias[rawKey];
  if (!mapKey || !cols[mapKey]) continue;
  let cellValue = rawVal === null || rawVal === undefined ? '' : String(rawVal);
  if (mapKey === 'status' && changes.statusDetail && statusToExcelText[changes.statusDetail]) {
    cellValue = statusToExcelText[changes.statusDetail];
  }
  patches.push({
    field: rawKey,
    colLetter: cols[mapKey],
    address: `${cols[mapKey]}${sourceRow}`,
    value: cellValue
  });
}

const shareUrl = 'https://perkinthailand-my.sharepoint.com/:x:/r/personal/chittiporn_p_perkin-logistics_com/_layouts/15/Doc.aspx?sourcedoc=%7BAFD2AA7F-6308-4DCE-9963-C9D64EAA0745%7D&file=JOB_Daily_2026%20STATUS_Dashboard.xlsx';
const shareId = 'u!' + Buffer.from(shareUrl, 'utf8')
  .toString('base64')
  .replace(/=+$/, '')
  .replace(/\//g, '_')
  .replace(/\+/g, '-');

return [{
  json: {
    editId,
    jobNo,
    sourceSheet,
    sourceRow,
    expectedVersion,
    changes,
    patches,
    driveItemUrl: `https://graph.microsoft.com/v1.0/shares/${shareId}/driveItem`
  }
}];

parameters.jsonBody:
={{ (() => {
  const driveId = $('Node 3: Resolve driveId & itemId').first().json.parentReference.driveId;
  const itemId = $('Node 3: Resolve driveId & itemId').first().json.id;
  const sessionId = $json.id;
  const mapped = $('Node 2: Map Web Fields (SHEET_COLUMN_MAP)').first().json;
  return JSON.stringify({
    requests: mapped.patches.map((p, idx) => ({
      id: String(idx + 1),
      method: 'PATCH',
      url: `/drives/${driveId}/items/${itemId}/workbook/worksheets('${encodeURIComponent(mapped.sourceSheet)}')/range(address='${p.address}')`,
      headers: {
        'workbook-session-id': sessionId,
        'Content-Type': 'application/json'
      },
      body: { values: [[p.value]] }
    }))
  });
})() }}

parameters.query:
={{ (() => {
  const m = $('Node 2: Map Web Fields (SHEET_COLUMN_MAP)').first().json;
  const c = m.changes || {};
  const q = (v) => (v === null || v === undefined || v === '') ? 'NULL' : `'${String(v).replace(/'/g, "''")}'`;
  return `
UPDATE jobs
SET status = COALESCE(${q(c.status)}, status),
    status_detail = COALESCE(${q(c.statusDetail)}, status_detail),
    etd = ${c.etd ? q(c.etd) + '::date' : 'etd'},
    eta = ${c.eta ? q(c.eta) + '::date' : 'eta'},
    draft_date = ${c.draftDate !== undefined ? (c.draftDate ? q(c.draftDate) + '::date' : 'NULL') : 'draft_date'},
    draft_customs = (${c.draftDate !== undefined ? (c.draftDate ? 'TRUE' : 'FALSE') : 'draft_customs'}),
    customs_date = ${c.customsDate !== undefined ? (c.customsDate ? q(c.customsDate) + '::date' : 'NULL') : 'customs_date'},
    customs_filed = (${c.customsDate !== undefined ? (c.customsDate ? 'TRUE' : 'FALSE') : 'customs_filed'}),
    do_date = ${c.doDate !== undefined ? (c.doDate ? q(c.doDate) + '::date' : 'NULL') : 'do_date'},
    do_released = (${c.doDate !== undefined ? (c.doDate ? 'TRUE' : 'FALSE') : 'do_released'}),
    clear_date = ${c.clearDate !== undefined ? (c.clearDate ? q(c.clearDate) + '::date' : 'NULL') : 'clear_date'},
    cleared = (${c.clearDate !== undefined ? (c.clearDate ? 'TRUE' : 'FALSE') : 'cleared'}),
    advance_date = ${c.advanceDate !== undefined ? (c.advanceDate ? q(c.advanceDate) + '::date' : 'NULL') : 'advance_date'},
    advance_doc = (${c.advanceDate !== undefined ? (c.advanceDate ? 'TRUE' : 'FALSE') : 'advance_doc'}),
    remark = COALESCE(${q(c.remark)}, remark),
    version = version + 1,
    updated_at = NOW()
WHERE job_no = ${q(m.jobNo)} AND version = ${Number(m.expectedVersion || 1)};

UPDATE job_edits
SET status = 'done',
    applied_at = NOW()
WHERE id = ${q(m.editId)}::uuid;
`;
})() }}
